from collections import Counter

def _runs(vals, bg):
    runs=[]; i=0
    while i<len(vals):
        if vals[i]==bg:
            i+=1; continue
        j=i+1
        while j<len(vals) and vals[j]==vals[i]:
            j+=1
        if j-i>=2:
            runs.append((i,j,vals[i]))
        i=j
    return runs

def transform(grid):
    src=[row[:] for row in grid]
    out=[row[:] for row in grid]
    h,w=len(src),len(src[0])
    bg=Counter(v for row in src for v in row).most_common(1)[0][0]
    sides={
        'top':_runs(src[0],bg),
        'bottom':_runs(src[-1],bg),
        'left':_runs([src[r][0] for r in range(h)],bg),
        'right':_runs([src[r][-1] for r in range(h)],bg),
    }
    bars=set()
    for side,runs in sides.items():
        for lo,hi,_ in runs:
            for t in range(lo,hi):
                bars.add((0,t) if side=='top' else (h-1,t) if side=='bottom' else (t,0) if side=='left' else (t,w-1))
    dots=[(r,c,src[r][c]) for r in range(h) for c in range(w) if src[r][c]!=bg and (r,c) not in bars]
    if not dots:
        return out
    ink=Counter(v for _,_,v in dots).most_common(1)[0][0]
    for first,second,axis in [('top','bottom','col'),('left','right','row')]:
        for a in sides[first]:
            for b in sides[second]:
                if a[1]-a[0] != b[1]-b[0]:
                    continue
                offsets=set()
                for r,c,_ in dots:
                    q=c if axis=='col' else r
                    if a[0]<=q<a[1]: offsets.add(q-a[0])
                    if b[0]<=q<b[1]: offsets.add(q-b[0])
                for side,run in ((first,a),(second,b)):
                    for off in offsets:
                        k=run[0]+off
                        if side=='top': r,c,dr,dc=1,k,1,0
                        elif side=='bottom': r,c,dr,dc=h-2,k,-1,0
                        elif side=='left': r,c,dr,dc=k,1,0,1
                        else: r,c,dr,dc=k,w-2,0,-1
                        while 0<=r<h and 0<=c<w:
                            if src[r][c]==bg:
                                out[r][c]=ink
                            else:
                                out[r][c]=4
                                break
                            r+=dr; c+=dc
    return out

